-- Migração 25 (cw_nonprod): ficha como funil comercial, pastas de documentos, módulos por cliente. Cole no SQL Editor e execute.
begin;
-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 16: commercial flow on one record, standard document folders, modules per client (D-051). Additive.
-- A prospect gets the same patrimonial record as a client (clients.is_prospect = true) so registration data, family,
-- patrimony and documents are captured in the same format before conversion. Prospects stay out of the client portfolio.

alter table cw_nonprod.clients add column is_prospect boolean not null default false;

-- Staff overview (portfolio, client lists): clients only, never prospect records.
create or replace function cw_nonprod.staff_client_overview()
returns table (client_id uuid, display_name text, client_code text, client_status text, onboarding text)
language sql stable security definer set search_path = '' as $$
  select c.id, c.display_name, s.client_code, c.status::text,
    case
      when exists (select 1 from cw_nonprod.client_users cu join cw_nonprod.profiles p on p.id = cu.user_id
                    where cu.client_id = c.id and p.status = 'ACTIVE') then 'ACTIVE'
      when exists (select 1 from cw_nonprod.client_users cu join cw_nonprod.profiles p on p.id = cu.user_id
                    where cu.client_id = c.id and p.status = 'INVITED') then 'SETUP_PENDING'
      when exists (select 1 from cw_nonprod.invitations i
                    where i.client_id = c.id and i.status = 'PENDING' and i.expires_at > now()) then 'INVITED'
      else 'NOT_INVITED'
    end
  from cw_nonprod.clients c join cw_nonprod.client_staff_info s on s.client_id = c.id
  where cw_nonprod_private.is_staff() and cw_nonprod_private.can_access_client(c.id) and not c.is_prospect
  order by c.display_name
$$;

-- The contact owner keeps access to the record (same rule as the conversion).
create function cw_nonprod_private.grant_contact_owner(p_owner uuid, p_client uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from cw_nonprod.profiles where id = p_owner and role = 'CONSULTANT')
     and not exists (select 1 from cw_nonprod.consultant_client_access
                      where consultant_id = p_owner and client_id = p_client and status = 'ACTIVE') then
    insert into cw_nonprod.consultant_client_access (consultant_id, client_id, assigned_by) values (p_owner, p_client, auth.uid());
    perform cw_nonprod_private.write_audit('PERMISSION_CHANGE', 'consultant_client_access', p_client::text, p_client, null,
      jsonb_build_object('consultant_id', p_owner, 'status', 'ACTIVE', 'via', 'crm_record'));
  end if;
end $$;

-- Record of a prospect: created once, idempotent. The contact stays PROSPECT until converted.
create function cw_nonprod.crm_prospect_record(p_contact uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare c cw_nonprod.crm_contacts; v_client uuid;
begin
  perform cw_nonprod_private.require_contact(p_contact);
  select * into c from cw_nonprod.crm_contacts where id = p_contact for update;
  if c.client_id is not null then return c.client_id; end if;
  if c.status <> 'PROSPECT' then perform cw_nonprod_private.deny(); end if;
  v_client := cw_nonprod.create_client(c.full_name);
  update cw_nonprod.clients set is_prospect = true where id = v_client;
  perform cw_nonprod_private.grant_contact_owner(c.owner_id, v_client);
  update cw_nonprod.crm_contacts set client_id = v_client, family_member_id = cw_nonprod_private.primary_member(v_client), updated_at = now()
   where id = p_contact;
  update cw_nonprod.crm_opportunities set client_id = v_client, updated_at = now() where contact_id = p_contact and client_id is null;
  return v_client;
end $$;

-- Conversion: needs a signed advisory contract on the prospect record (unless attaching to an existing client).
-- The record is kept (same data); it only stops being a prospect.
create or replace function cw_nonprod.crm_convert_contact(p_contact uuid, p_client uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare c cw_nonprod.crm_contacts; v_client uuid;
begin
  perform cw_nonprod_private.require_contact(p_contact);
  select * into c from cw_nonprod.crm_contacts where id = p_contact for update;
  if c.status = 'CLIENT' then return c.client_id; end if;                -- repeated call: same client, nothing new
  if p_client is null and not exists (select 1 from cw_nonprod.client_contracts where client_id = c.client_id and status = 'SIGNED') then
    raise exception 'contract not signed' using errcode = '22023';   -- commercial flow: signed contract before conversion
  end if;
  if c.client_id is not null then
    v_client := c.client_id;
    update cw_nonprod.clients set is_prospect = false, updated_at = now() where id = v_client;
  elsif p_client is not null then
    perform cw_nonprod_private.require_client(p_client);
    v_client := p_client;
  else
    v_client := cw_nonprod.create_client(c.full_name);
  end if;
  perform cw_nonprod_private.grant_contact_owner(c.owner_id, v_client);
  update cw_nonprod.crm_contacts
     set status = 'CLIENT', client_id = v_client,
         family_member_id = coalesce(family_member_id, case when p_client is null then cw_nonprod_private.primary_member(v_client) end), updated_at = now()
   where id = p_contact;
  update cw_nonprod.crm_opportunities set client_id = v_client, updated_at = now() where contact_id = p_contact and client_id is null;
  insert into cw_nonprod.crm_history (contact_id, event, to_value, actor_id) values (p_contact, 'CONVERTED', v_client::text, auth.uid());
  return v_client;
end $$;

-- ---------------------------------------------------------------- standard folders
-- 1 Documentos pessoais · 2 Contrato e NDA · 3 Extratos e posições · 4 Relatórios mensais · 5 Análises e planejamento
-- 6 Financeiro · 7 Diversos. Folder documents belong to the CRM contact (no automatic deletion, D-040).
alter table cw_nonprod.documents add column folder smallint check (folder between 1 and 7);
update cw_nonprod.documents set folder = case purpose when 'CONTRACT' then 2 when 'PROPOSAL' then 5 else 7 end
 where contact_id is not null and folder is null;

create function cw_nonprod.crm_document_begin_folder(p_contact uuid, p_folder integer, p_format text, p_mime text, p_filename text,
                                                p_size integer, p_sha256 text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if p_folder is null or p_folder not between 1 and 7 then raise exception 'invalid folder' using errcode = '22023'; end if;
  v_id := cw_nonprod.crm_document_begin(p_contact, case when p_folder = 2 then 'CONTRACT' else 'CRM_OTHER' end,
                                   p_format, p_mime, p_filename, p_size, p_sha256);
  update cw_nonprod.documents set folder = p_folder where id = v_id;
  return v_id;
end $$;

create function cw_nonprod.crm_document_set_folder(p_document uuid, p_folder integer) returns void
language plpgsql security definer set search_path = '' as $$
declare v_contact uuid;
begin
  if p_folder is null or p_folder not between 1 and 7 then raise exception 'invalid folder' using errcode = '22023'; end if;
  select contact_id into v_contact from cw_nonprod.documents where id = p_document and status = 'STORED';
  if v_contact is null then perform cw_nonprod_private.deny(); end if;
  perform cw_nonprod_private.require_contact(v_contact);
  update cw_nonprod.documents set folder = p_folder where id = p_document;
end $$;

-- ---------------------------------------------------------------- modules visible per client (staff decides)
alter table cw_nonprod.clients add column modules text[] not null
  default array['TRANSACTIONS', 'WEALTH', 'CASHFLOW', 'GOALS', 'SUCCESSION', 'PROTECTION', 'TAX', 'REPORT']
  check (modules <@ array['TRANSACTIONS', 'WEALTH', 'CASHFLOW', 'GOALS', 'SUCCESSION', 'PROTECTION', 'TAX', 'REPORT']);

create function cw_nonprod.client_modules_save(p_client uuid, p_modules text[]) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_staff() then perform cw_nonprod_private.deny(); end if;
  perform cw_nonprod_private.require_client(p_client);
  update cw_nonprod.clients set modules = (select coalesce(array_agg(distinct m order by m), '{}') from unnest(p_modules) m), updated_at = now()
   where id = p_client;
  perform cw_nonprod_private.write_audit('UPDATE', 'clients', p_client::text, p_client, null, jsonb_build_object('modules', p_modules));
end $$;

revoke all on function cw_nonprod_private.grant_contact_owner(uuid, uuid) from public, anon, authenticated;
revoke all on function cw_nonprod.client_modules_save(uuid, text[]), cw_nonprod.crm_prospect_record(uuid), cw_nonprod.crm_document_begin_folder(uuid, integer, text, text, text, integer, text),
  cw_nonprod.crm_document_set_folder(uuid, integer) from public, anon, authenticated;
grant execute on function cw_nonprod.client_modules_save(uuid, text[]), cw_nonprod.crm_prospect_record(uuid), cw_nonprod.crm_document_begin_folder(uuid, integer, text, text, text, integer, text),
  cw_nonprod.crm_document_set_folder(uuid, integer) to authenticated;
commit;
select 'migração 25 ok' as resultado, count(*) as colunas from information_schema.columns where table_schema = 'cw_nonprod' and ((table_name = 'clients' and column_name in ('is_prospect', 'modules')) or (table_name = 'documents' and column_name = 'folder'));
